def above_threshold(data, epsilon, rng):
	# Add Laplace noise to the threshold once
	T = 4 + rng.laplace(0, 1 / data.count(1))
	# Add fresh Laplace noise to each query answer
	num_ones = data.count(1) + rng.laplace(0, 1 / data.count(1))
	num_zeros = data.count(0) + rng.laplace(0, 1 / data.count(0))
	total_elements = len(data) + rng.laplace(0, 1 / len(data))
	# Stop at the first noisy crossing
	if num_ones > T:
		return 1
	elif num_zeros > T:
		return 2
	elif total_elements > T:
		return 3
	else:
		return 0

